package at.hausgarten.service;

import android.app.job.JobInfo;
import org.json.*;
import java.io.*;

/** Real SQLite/Keystore plus shared backup runner, never a Google account or device setting. */
final class BackupAutomationNativeAcceptance {
    private static void denied(PixelMcpInstrumentation.Task action)throws Exception {try{action.run();}catch(Exception expected){return;}throw new AssertionError("Expected backup setup refusal");}
    static void run(PixelMcpInstrumentation test)throws Exception {
        test.probe("posted main-thread scheduler failure and rejection retain a real committed order and durable retry without legacy dispatch",()->{try(OwnerNativeAcceptance.Fixture f=new OwnerNativeAcceptance.Fixture(test.getTargetContext())){
            java.util.concurrent.CountDownLatch[] done={new java.util.concurrent.CountDownLatch(1)};java.util.concurrent.atomic.AtomicInteger localCalls=new java.util.concurrent.atomic.AtomicInteger(),legacyCalls=new java.util.concurrent.atomic.AtomicInteger();java.util.concurrent.atomic.AtomicBoolean fail=new java.util.concurrent.atomic.AtomicBoolean(true),accept=new java.util.concurrent.atomic.AtomicBoolean(true),post=new java.util.concurrent.atomic.AtomicBoolean(true),onMain=new java.util.concurrent.atomic.AtomicBoolean();
            BackgroundWorkDispatch.Host host=new BackgroundWorkDispatch.Host(){public void state(boolean pending,String code){try{f.store.putOwnerValue("qa_background_dispatch",new JSONObject().put("pending",pending).put("code",code).toString());}catch(Exception error){throw new RuntimeException(error);}if(!code.isEmpty()||!pending)done[0].countDown();}public boolean post(Runnable task){return post.get()&&new android.os.Handler(android.os.Looper.getMainLooper()).post(task);}public boolean localMode(){return true;}public boolean localReady(){return true;}public boolean local(long delay){onMain.set(android.os.Looper.myLooper()==android.os.Looper.getMainLooper());localCalls.incrementAndGet();if(fail.get())throw new IllegalStateException("qa scheduler injected failure");return accept.get();}public boolean legacy(long delay){legacyCalls.incrementAndGet();return true;}};
            String customer=PixelMcpReadTools.effective(f.store.getState()).getJSONArray("customers").getJSONObject(0).getString("id");JSONObject payload=new JSONObject().put("id","qa_async_committed_order").put("customer_id",customer).put("title","QA committed before posted failure").put("_request_id","qa_async_committed_order_action");BusinessDataBridge bridge=new BusinessDataBridge(f.context,f.store,null,()->BackgroundWorkDispatch.request(0,host));test.yes(bridge.saveOrder(payload.toString()).equals("qa_async_committed_order"));if(!done[0].await(10,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("QA posted callback missing");JSONObject failed=new JSONObject(f.store.ownerValue("qa_background_dispatch","{}"));test.yes(onMain.get()&&failed.getBoolean("pending")&&failed.getString("code").equals("BACKGROUND_SCHEDULING_FAILED")&&legacyCalls.get()==0);test.yes(PixelMcpWriteTools.find(PixelMcpReadTools.effective(f.store.getState()).getJSONArray("orders"),"qa_async_committed_order").getString("title").equals(payload.getString("title")));
            done[0]=new java.util.concurrent.CountDownLatch(1);fail.set(false);accept.set(false);BackgroundWorkDispatch.request(0,host);if(!done[0].await(10,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("QA rejected callback missing");test.yes(new JSONObject(f.store.ownerValue("qa_background_dispatch","{}")).getString("code").equals("BACKGROUND_SCHEDULER_UNAVAILABLE"));
            done[0]=new java.util.concurrent.CountDownLatch(1);post.set(false);int before=localCalls.get();BackgroundWorkDispatch.request(0,host);test.yes(localCalls.get()==before&&new JSONObject(f.store.ownerValue("qa_background_dispatch","{}")).getString("code").equals("BACKGROUND_HANDLER_UNAVAILABLE"));
            done[0]=new java.util.concurrent.CountDownLatch(1);post.set(true);accept.set(true);BackgroundWorkDispatch.request(0,host);if(!done[0].await(10,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("QA resumed callback missing");test.yes(!new JSONObject(f.store.ownerValue("qa_background_dispatch","{}")).getBoolean("pending")&&legacyCalls.get()==0);done[0]=new java.util.concurrent.CountDownLatch(1);test.yes(bridge.saveOrder(payload.toString()).equals("qa_async_committed_order"));if(!done[0].await(10,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("QA replay callback missing");int count=0;JSONArray orders=PixelMcpReadTools.effective(f.store.getState()).getJSONArray("orders");for(int i=0;i<orders.length();i++)if(orders.getJSONObject(i).getString("id").equals("qa_async_committed_order"))count++;test.yes(count==1);
        }});
        test.probe("backup native settings require explicit recovery setup and retain atomic CAS replay across reopen and restore context",()->{try(OwnerNativeAcceptance.Fixture f=new OwnerNativeAcceptance.Fixture(test.getTargetContext())){
            BackupRecoveryKeyStore keys=new BackupRecoveryKeyStore(f.context);try{
                BackupSettingsRepository settings=new BackupSettingsRepository(f.context,f.store);JSONObject before=settings.read();test.yes(!before.getBoolean("enabled")&&!before.getBoolean("contextMatches")&&!before.getBoolean("keyConfigured")&&before.getBoolean("unmeteredOnly"));
                denied(()->settings.configure("qa_auto_no_key",before.getString("revision"),true,"qa_backup@example.invalid","qa_service_folder_123",true));test.yes(!settings.read().getBoolean("enabled"));
                String code=BackupCrypto.newRecoveryCode();keys.confirmAndStore("qa_auto_key_setup",code,code);String revision=settings.read().getString("revision");
                f.store.getWritableDatabase().execSQL("CREATE TEMP TRIGGER qa_backup_config_abort BEFORE INSERT ON owner_state WHEN NEW.key LIKE 'full_backup_settings_request:%' BEGIN SELECT RAISE(ABORT,'qa atomic config failure'); END");
                denied(()->settings.configure("qa_auto_atomic_config",revision,true,"qa_backup@example.invalid","qa_service_folder_123",true));test.yes(settings.read().getString("revision").equals(revision));f.store.getWritableDatabase().execSQL("DROP TRIGGER qa_backup_config_abort");
                JSONObject configured=settings.configure("qa_auto_atomic_config",revision,true,"qa_backup@example.invalid","qa_service_folder_123",true);test.yes(configured.getBoolean("enabled")&&configured.getBoolean("contextMatches")&&!configured.getBoolean("replayed"));
                test.yes(settings.configure("qa_auto_atomic_config",revision,true,"qa_backup@example.invalid","qa_service_folder_123",true).getBoolean("replayed"));
                denied(()->settings.configure("qa_auto_atomic_config",revision,true,"qa_changed@example.invalid","qa_service_folder_123",true));denied(()->settings.configure("qa_auto_stale_config",revision,false,"qa_backup@example.invalid","qa_service_folder_123",true));
                JSONObject browser=new JSONObject().put("formatVersion",1).put("storage",new JSONObject().put("qa_draft","QA pending draft"));String br=settings.browserRevision();settings.saveBrowser("qa_auto_browser_save",br,browser);test.yes(settings.saveBrowser("qa_auto_browser_save",br,browser).getBoolean("replayed")&&settings.browser().getJSONObject("browser").getJSONObject("storage").getString("qa_draft").equals("QA pending draft"));
                denied(()->settings.saveBrowser("qa_auto_browser_changed",br,new JSONObject().put("formatVersion",1).put("storage",new JSONObject().put("qa_draft","QA changed"))));
                denied(()->settings.saveBrowser("qa_auto_browser_invalid",settings.browserRevision(),new JSONObject().put("formatVersion",1).put("storage",new JSONObject().put("qa_number",1))));
                f.store.close();try(PixelLocalStore reopened=new PixelLocalStore(f.context)){
                    BackupSettingsRepository saved=new BackupSettingsRepository(f.context,reopened);test.yes(saved.read().getBoolean("enabled")&&saved.browser().getJSONObject("browser").getJSONObject("storage").has("qa_draft"));BackupDeviceGuard guard=new BackupDeviceGuard(f.context);JSONObject identity=guard.current();
                    JSONObject newer=new JSONObject().put("formatVersion",2).put("backupId","qa_newer_job").put("installationId",identity.getString("installationId")).put("restoreEpoch",identity.getString("restoreEpoch")).put("createdAt",java.time.Instant.now().toString()).put("phase","qa_newer_phase").put("destination",new JSONObject().put("kind","drive"));reopened.putOwnerValue("backup_job:qa_newer_job",newer.toString());test.yes(new BackupAutomation(f.context,reopened).decision(System.currentTimeMillis()).getString("action").equals("CREATE"));test.yes(reopened.ownerValue("backup_job:qa_newer_job","").equals(newer.toString()));
                    guard.advanceForRestore("qa_auto_restore_epoch",guard.current().getString("restoreEpoch"));test.yes(!saved.read().getBoolean("contextMatches"));denied(()->saved.browser());test.yes(new BackupAutomation(f.context,reopened).decision(System.currentTimeMillis()).getString("action").equals("DISABLED"));
                }
            }finally{BackupCoreNativeAcceptance.deleteQaKey(f,keys);}
        }});
        test.probe("backup native automatic runner resumes lost upload once with bounded retry and uses data age not new verification time",()->{try(OwnerNativeAcceptance.Fixture f=new OwnerNativeAcceptance.Fixture(test.getTargetContext())){
            BackupRecoveryKeyStore keys=new BackupRecoveryKeyStore(f.context);try{
                String code=BackupCrypto.newRecoveryCode();keys.confirmAndStore("qa_runner_key_setup",code,code);BackupSettingsRepository settings=new BackupSettingsRepository(f.context,f.store);settings.configure("qa_runner_settings",settings.read().getString("revision"),true,"qa_backup@example.invalid","qa_service_folder_123",true);settings.saveBrowser("qa_runner_browser",settings.browserRevision(),new JSONObject().put("formatVersion",1).put("storage",new JSONObject().put("qa_draft","QA active editor")));
                BackupServiceNativeAcceptance.Server server=new BackupServiceNativeAcceptance.Server(new File(f.context.getCacheDir(),"qa_automatic_remote.hgb"));LocalBackupCoordinator service=new LocalBackupCoordinator(f.context,f.store,server,account->"qa_backup_token");BackupAutomation runner=new BackupAutomation(f.context,f.store,service,()->"qa_automatic_backup");long now=System.currentTimeMillis();String business=PixelMcpWriteTools.hash(f.store.getState().getJSONObject("master"));
                JSONObject first=runner.run(now);test.yes(first.getString("action").equals("WAIT")&&first.getLong("nextAttemptAt")>=now+30000&&server.completed==1);String id=first.getString("backupId");test.yes(service.status(id).getInt("attempts")==1&&runner.run(now+1000).getString("action").equals("WAIT"));
                f.store.close();try(PixelLocalStore reopened=new PixelLocalStore(f.context)){LocalBackupCoordinator resumed=new LocalBackupCoordinator(f.context,reopened,server,account->"qa_backup_token");BackupAutomation next=new BackupAutomation(f.context,reopened,resumed);JSONObject completed=next.run(first.getLong("nextAttemptAt"));test.yes(completed.getString("action").equals("COMPLETED")&&completed.getString("backupId").equals(id)&&server.starts==1&&server.completed==1&&server.readbacks==1);JSONObject job=resumed.status(id);test.yes(job.getInt("attempts")==2&&job.getJSONObject("archive").has("capturedAt"));test.yes(next.decision(now+60000).getString("action").equals("WAIT"));test.yes(next.decision(now+2*BackupScheduleRules.INTERVAL_MS).getString("action").equals("CREATE"));test.yes(PixelMcpWriteTools.hash(reopened.getState().getJSONObject("master")).equals(business));}
            }finally{BackupCoreNativeAcceptance.deleteQaKey(f,keys);}
        }});
        test.probe("offline local backup generation and a valid job continue beside an invalid job and older pending upload",()->{try(OwnerNativeAcceptance.Fixture f=new OwnerNativeAcceptance.Fixture(test.getTargetContext())){
            BackupRecoveryKeyStore keys=new BackupRecoveryKeyStore(f.context);try{String code=BackupCrypto.newRecoveryCode();keys.confirmAndStore("qa_independent_jobs_key",code,code);BackupSettingsRepository settings=new BackupSettingsRepository(f.context,f.store);settings.configure("qa_independent_jobs_settings",settings.read().getString("revision"),true,"qa_backup@example.invalid","qa_service_folder_123",true);settings.saveBrowser("qa_independent_jobs_browser",settings.browserRevision(),new JSONObject().put("formatVersion",1).put("storage",new JSONObject()));java.util.concurrent.atomic.AtomicInteger network=new java.util.concurrent.atomic.AtomicInteger(),ids=new java.util.concurrent.atomic.AtomicInteger();DriveRestClient.Wire offline=(method,url,headers,body,maximum)->{network.incrementAndGet();throw new IOException("qa_offline");};LocalBackupCoordinator service=new LocalBackupCoordinator(f.context,f.store,offline,account->{network.incrementAndGet();throw new IOException("qa_offline");});BackupAutomation runner=new BackupAutomation(f.context,f.store,service,()->"qa_independent_generation_"+ids.incrementAndGet());long now=System.currentTimeMillis();JSONObject first=runner.runLocal(now);test.yes(first.getString("action").equals("PREPARED")&&network.get()==0);String old=first.getString("backupId");test.yes(service.status(old).getString("phase").equals("LOCAL_VERIFIED"));
                JSONObject destination=FullBackupController.destination(settings.read());service.create("qa_bad_job_request","qa_bad_job",destination,new JSONObject().put("formatVersion",1).put("storage",new JSONObject()));String badKey="backup_job:qa_bad_job",raw=f.store.ownerValue(badKey,"");if(raw.isEmpty())throw new AssertionError("QA expected existing job key");String invalid=new JSONObject(raw).put("formatVersion",2).toString();f.store.putOwnerValue(badKey,invalid);
                JSONObject next=runner.runLocal(now+2*BackupScheduleRules.INTERVAL_MS);test.yes(next.getString("action").equals("PREPARED")&&!next.getString("backupId").equals(old)&&network.get()==0);test.yes(f.store.ownerValue(badKey,"").equals(invalid)&&service.status(old).getString("phase").equals("LOCAL_VERIFIED"));service.create("qa_good_job_request","qa_good_job",destination,new JSONObject().put("formatVersion",1).put("storage",new JSONObject()));JSONObject good=runner.runLocal(now+2*BackupScheduleRules.INTERVAL_MS);test.yes(good.getString("action").equals("PREPARED")&&good.getString("backupId").equals("qa_good_job")&&network.get()==0);test.yes(service.status("qa_good_job").getJSONObject("archive").has("localVerifiedAt"));
            }finally{BackupCoreNativeAcceptance.deleteQaKey(f,keys);}
        }});
        test.probe("backup native scheduler separates offline daily preparation from network constrained upload without exact deadline",()->{
            JobInfo daily=FullBackupJob.specification(test.getTargetContext(),true,true,0),once=FullBackupJob.specification(test.getTargetContext(),false,false,60000);
            // Actual API30 reports zero for an unset override deadline (standalone native probe).
            test.yes(daily.isPeriodic()&&daily.isPersisted()&&daily.getIntervalMillis()==BackupScheduleRules.INTERVAL_MS&&daily.getNetworkType()==JobInfo.NETWORK_TYPE_NONE&&daily.getMaxExecutionDelayMillis()==0);
            test.yes(!once.isPeriodic()&&once.isPersisted()&&once.getMinLatencyMillis()==60000&&once.getNetworkType()==JobInfo.NETWORK_TYPE_ANY&&once.getMaxExecutionDelayMillis()==0);
            JobInfo local=FullBackupJob.localSpecification(test.getTargetContext(),0);test.yes(local.getNetworkType()==JobInfo.NETWORK_TYPE_NONE&&!local.isPeriodic()&&local.isPersisted());
            try(OwnerNativeAcceptance.Fixture isolated=new OwnerNativeAcceptance.Fixture(test.getTargetContext())){JobInfo scoped=FullBackupJob.localSpecification(isolated.context,0);test.yes(FullBackupJob.matchesStorageScope(isolated.context,scoped.getExtras())&&!FullBackupJob.matchesStorageScope(test.getTargetContext(),scoped.getExtras()));}
        });
    }
}
